// seriesParsed builds the parsed fact view of a serial-record document
// (design.md §Interfaces §1 — the facts the serial-scanner stamps).
func seriesParsed(dirNameRaw, seriesRel string) map[string]any {
	return map[string]any{
		"serial_record":        true,
		"dir_name_raw":         dirNameRaw,
		"backing":              "directory",
		"series_relative_path": seriesRel,
	}
}

// episodeParsed builds the parsed fact view of an episode item (§Interfaces §2).
func episodeParsed(rel string) map[string]any {
	return map[string]any{"relative_path": rel, "series_relative_path": parentOf(rel)}
}

func parentOf(rel string) string {
	for i := len(rel) - 1; i >= 0; i-- {
		if rel[i] == '/' {
			return rel[:i]
		}
	}
	return rel
}

// runChain drives the full 4-RPC chain over one document and returns whether
// Match applied, the resulting namespace proposal, and the Match reason.
func runChain(t *testing.T, parsed map[string]any) (bool, map[string]any, string) {
	t.Helper()
	impl := &parserImpl{}
	ctx := context.Background()
	parsedStruct, err := structpb.NewStruct(parsed)
	if err != nil {
		t.Fatalf("parsed struct: %v", err)
	}
	match, err := impl.Match(ctx, &metadatav1.MatchRequest{
		Item: &scannerv1.IdentifyResult{Parsed: parsedStruct},
	})
	if err != nil {
		t.Fatalf("Match: %v", err)
	}
	if !match.GetApplies() {
		return false, nil, match.GetReason()
	}
	if _, err := impl.BuildRequest(ctx, &metadatav1.BuildRequestRequest{Query: match.GetQuery()}); err != nil {
		t.Fatalf("BuildRequest: %v", err)
	}
	conv, err := impl.Convert(ctx, &metadatav1.ConvertRequest{Query: match.GetQuery()})
	if err != nil {
		t.Fatalf("Convert: %v", err)
	}
	merge, err := impl.Merge(ctx, &metadatav1.MergeRequest{
		Incoming: conv.GetMetadata(),
		PluginId: pluginID,
	})
	if err != nil {
		t.Fatalf("Merge: %v", err)
	}
	data := merge.GetDocument().GetData().AsMap()
	sources, _ := data["sources"].(map[string]any)
	ns, _ := sources[pluginID].(map[string]any)
	return true, ns, match.GetReason()
}

// TestSeriesTitleParse is box 3.2: a series document self-selects at Match and
// parses the raw directory facts into a cleaned display title plus the season
// (always present: the marker's value, else 1). The namespace carries ONLY
// those fields.
func TestSeriesTitleParse(t *testing.T) {
	cases := []struct {
		name       string
		dirNameRaw string
		wantTitle  string
		wantSeason float64
	}{
		{
			name:       "cyrillic mixed name with season token",
			dirNameRaw: "Необычный адвокат У Ён У Extraordinary Attorney Woo.2022.S01",
			wantTitle:  "Необычный адвокат У Ён У Extraordinary Attorney Woo 2022",
			wantSeason: 1,
		},
		{
			name:       "cours directory season marker",
			dirNameRaw: "Bleach S04 (2008)",
			wantTitle:  "Bleach",
			wantSeason: 4,
		},
		{
			name:       "nth season form",
			dirNameRaw: "Show_Name_4th_Season",
			wantTitle:  "Show Name",
			wantSeason: 4,
		},
		{
			name:       "no season token defaults the season to 1",
			dirNameRaw: "Seishun Buta Yarou",
			wantTitle:  "Seishun Buta Yarou",
			wantSeason: 1,
		},
		{
			name:       "an episode token is not a season token",
			dirNameRaw: "Specials.S01E01.SPECIAL",
			wantTitle:  "Specials S01E01 SPECIAL",
			wantSeason: 1,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			applies, ns, _ := runChain(t, seriesParsed(tc.dirNameRaw, tc.dirNameRaw))
			if !applies {
				t.Fatalf("Match did not apply to the series document")
			}
			if ns["title"] != tc.wantTitle {
				t.Fatalf("title = %q, want %q", ns["title"], tc.wantTitle)
			}
			if ns["season"] != tc.wantSeason {
				t.Fatalf("season = %v, want %v", ns["season"], tc.wantSeason)
			}
			if ns["dir_name_raw"] != tc.dirNameRaw {
				t.Fatalf("raw facts lost: %v", ns)
			}
		})
	}
}

// TestUnicodeTitlePreserved is the Unicode-first-class contract for the parser:
// the cleaned display title carries non-ASCII characters unmodified.
func TestUnicodeTitlePreserved(t *testing.T) {
	const dir = "Необычный адвокат У Ён У Extraordinary Attorney Woo.2022.S01"
	_, ns, _ := runChain(t, seriesParsed(dir, dir))
	title, _ := ns["title"].(string)
	for _, r := range []rune("НеобычныйадвокатЁнУ") {
		found := false
		for _, c := range title {
			if c == r {
				found = true
				break
			}
		}
		if !found {
			t.Fatalf("cleaned title %q lost non-ASCII character %q", title, string(r))
		}
	}
}

// TestEpisodeMatch is box 3.3's Match half: an episode document applies iff its
// filename carries an SxxExx token; non-match is applies=false (a skipped
// stage, not an error); a series document goes down the series branch.
func TestEpisodeMatch(t *testing.T) {
	impl := &parserImpl{}
	ctx := context.Background()

	matchDoc := func(parsed map[string]any) *metadatav1.MatchResult {
		t.Helper()
		st, err := structpb.NewStruct(parsed)
		if err != nil {
			t.Fatalf("parsed struct: %v", err)
		}
		res, err := impl.Match(ctx, &metadatav1.MatchRequest{Item: &scannerv1.IdentifyResult{Parsed: st}})
		if err != nil {
			t.Fatalf("Match: %v", err)
		}
		return res
	}

	// Applies: the SxxExx token selects season/episode into the query.
	res := matchDoc(episodeParsed("Show/Show.S01E02.1080p.mkv"))
	if !res.GetApplies() {
		t.Fatalf("episode with SxxExx did not apply")
	}
	q := res.GetQuery().AsMap()
	if q["season"] != float64(1) || q["episode"] != float64(2) {
		t.Fatalf("query = %v, want season 1 episode 2", q)
	}

	// Multi-episode token carries episode_end.
	res = matchDoc(episodeParsed("Show/Show.S02E10E11.mkv"))
	q = res.GetQuery().AsMap()
	if !res.GetApplies() || q["episode_end"] != float64(11) {
		t.Fatalf("multi-episode query = %v (applies=%v), want episode_end 11", q, res.GetApplies())
	}

	// Non-match: applies=false with a reason — never an error, never applied.
	// Numberless VIDEO names now APPLY on the film path (covered by
	// TestFilmMatch); the skip row left here is the non-video shape.
	res = matchDoc(episodeParsed("Show/Credits.ass")) // not even a video filename
	if res.GetApplies() || res.GetReason() == "" {
		t.Fatalf("non-video filename applied or skipped without a reason: %+v", res)
	}

	// A numberless video filename follows the film path: it applies with the
	// parsed title and no season or episode key.
	res = matchDoc(episodeParsed("Show/Feature.mkv"))
	if !res.GetApplies() || res.GetConfidence() != 0.6 {
		t.Fatalf("numberless video filename did not apply on the film path: %+v", res)
	}
	q = res.GetQuery().AsMap()
	if q["title"] != "Feature" || q["season"] != nil || q["episode"] != nil {
		t.Fatalf("film query = %v, want title Feature with no season/episode key", q)
	}
}

// TestFilmMatch is the film-path table (film-name-parsing 2.1): a numberless
// VIDEO filename applies through the shared grammar's no-season parse at
// confidence 0.6 — title plus the structured release fields it carries, and
// NEVER a season or episode key (the S01 marker of a season pack without an
// episode number is dropped on the film path). A non-video name stays a
// skipped stage with a reason. The numberless and below-1 zero rows moved
// here from TestEpisodeNameGrammar apply as films now.
func TestFilmMatch(t *testing.T) {
	cases := []struct {
		name       string
		rel        string
		wantApply  bool
		wantTitle  string
		wantFields map[string]any // the release fields beside the title; absent fields asserted absent
	}{
		// Ground-truth rows: the two real movie names — clean titles, the
		// release fields each carries, no season/episode key, confidence 0.6.
		{
			name:       "real movie, dash-form group after a consumed tag",
			rel:        "Show/Demon.Slayer.Kimetsu.No.Yaiba.Infinity.Castle.1080p.CR-Cassu.mkv",
			wantApply:  true,
			wantTitle:  "Demon Slayer Kimetsu No Yaiba Infinity Castle",
			wantFields: map[string]any{"resolution": "1080p"},
		},
		{
			name:      "real movie, amzn source and dot-form codec, year stays in title",
			rel:       "Show/Chainsaw.Man.The.Movie.Reze.Arc.2025.1080p.AMZN.WEB-DL.H.264-EniaHD.mkv",
			wantApply: true,
			wantTitle: "Chainsaw Man The Movie Reze Arc 2025",
			wantFields: map[string]any{
				"resolution": "1080p",
				"source":     "web-dl",
				"codec":      []any{"h.264"},
				"year":       float64(2025),
			},
		},
		// A season marker without an episode number applies as a film — the
		// marker itself is never emitted on the film path.
		{name: "season marker without an episode number drops the marker", rel: "Show/Show.S01.mkv", wantApply: true, wantTitle: "Show"},
		// Bare video names.
		{name: "bare video name applies with its title", rel: "Show/Feature.mkv", wantApply: true, wantTitle: "Feature"},
		// Non-video names stay skipped.
		{name: "non-video name stays skipped", rel: "Show/Credits.ass"},
		// Rows moved from TestEpisodeNameGrammar (the numberless + below-1
		// zero shapes): each applies as a film, never with an episode key.
		{name: "zero edge bracket is title text on the film path", rel: "Show/[00] Title.mkv", wantApply: true, wantTitle: "Title"},
		{name: "bare zero rides along in the title", rel: "Show/Title 0.mkv", wantApply: true, wantTitle: "Title 0"},
		{name: "zero cyrillic marker is title text on the film path", rel: "Show/Title 0 серия.mkv", wantApply: true, wantTitle: "Title 0 серия"},
		{name: "whole-token 720i is a resolution on the film path", rel: "Show/Title 720i.mkv", wantApply: true, wantTitle: "Title", wantFields: map[string]any{"resolution": "720i"}},
		{name: "tagged film stem parses through the film path", rel: "Show/Blue Horizon (2019) [WEB-DL 1080p x264].mkv", wantApply: true, wantTitle: "Blue Horizon",
			wantFields: map[string]any{"resolution": "1080p", "source": "web-dl", "codec": []any{"x264"}, "year": float64(2019)}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			applies, ns, reason := runChain(t, episodeParsed(tc.rel))
			if applies != tc.wantApply {
				t.Fatalf("applies = %v (reason %q), want %v", applies, reason, tc.wantApply)
			}
			if !tc.wantApply {
				if reason == "" {
					t.Fatalf("skip without a reason")
				}
				return
			}
			// The film path applies flat at 0.6 (design.md D-5).
			impl := &parserImpl{}
			st, err := structpb.NewStruct(episodeParsed(tc.rel))
			if err != nil {
				t.Fatalf("parsed struct: %v", err)
			}
			res, err := impl.Match(context.Background(), &metadatav1.MatchRequest{Item: &scannerv1.IdentifyResult{Parsed: st}})
			if err != nil {
				t.Fatalf("Match: %v", err)
			}
			if res.GetConfidence() != 0.6 {
				t.Fatalf("confidence = %v, want 0.6", res.GetConfidence())
			}
			// Title plus exactly the release fields — no season or episode
			// key is ever fabricated on the film path.
			if ns["title"] != tc.wantTitle {
				t.Fatalf("title = %q, want %q", ns["title"], tc.wantTitle)
			}
			for _, never := range []string{"season", "episode"} {
				if _, ok := ns[never]; ok {
					t.Fatalf("film namespace carries %q: %v", never, ns)
				}
			}
			for field, want := range tc.wantFields {
				if !reflect.DeepEqual(ns[field], want) {
					t.Fatalf("%s = %v, want %v", field, ns[field], want)
				}
			}
			if len(ns) != len(tc.wantFields)+1 {
				t.Fatalf("namespace = %v, want exactly title + the %d carried fields", ns, len(tc.wantFields))
			}
		})
	}
}

// TestSeriesNameGrammar is the name-grammar table (change serial boxes 1.1 +
// 1.2): series directory and file-backed names parse to a stripped title, an
// always-present season, and a confidence steered by marker explicitness.
// Derived rows come from the real-collection shape inventory (design.md D-8),
// titles and group names neutralized.
func TestSeriesNameGrammar(t *testing.T) {
	cases := []struct {
		name       string
		dirNameRaw string
		backing    string // "file" for a file-backed serial name, else "directory"
		wantTitle  string
		wantSeason float64
		wantConf   float64
	}{
		// Box 1.1 ground-truth rows.
		{name: "file-backed roman sequel suffix", dirNameRaw: "Black_Clover_II_[01].mkv", backing: "file", wantTitle: "Black Clover", wantSeason: 2, wantConf: 1.0},
		{name: "TV N marker", dirNameRaw: "Aria TV 1", wantTitle: "Aria", wantSeason: 1, wantConf: 1.0},
		{name: "standalone Sxx marker", dirNameRaw: "Black Clover S2", wantTitle: "Black Clover", wantSeason: 2, wantConf: 1.0},
		{name: "explicit S01 confidence shape", dirNameRaw: "Show Name S01", wantTitle: "Show Name", wantSeason: 1, wantConf: 1.0},
		// Box 1.1 derived rows (design.md D-8), neutralized.
		{name: "TV hyphen form", dirNameRaw: "Azure Harbor TV-2", wantTitle: "Azure Harbor", wantSeason: 2, wantConf: 1.0},
		{name: "Season N word form", dirNameRaw: "Crimson Vale Season 2", wantTitle: "Crimson Vale", wantSeason: 2, wantConf: 1.0},
		{name: "roman sequel folder", dirNameRaw: "Ivory Tower II", wantTitle: "Ivory Tower", wantSeason: 2, wantConf: 1.0},
		{name: "roman sequel folder VIII", dirNameRaw: "Quiet Meadow_VIII", wantTitle: "Quiet Meadow", wantSeason: 8, wantConf: 1.0},
		{name: "bracket-train-only folder falls back to the raw cleaned name", dirNameRaw: "[TV-1] [2023] [WEBRip] [1080p] [RUS + ENG] [Multi5-Subs]", wantTitle: "[TV-1] [2023] [WEBRip] [1080p] [RUS + ENG] [Multi5-Subs]", wantSeason: 1, wantConf: 0.6},
		{name: "trailing bare digit is not a season marker", dirNameRaw: "Title 0", wantTitle: "Title 0", wantSeason: 1, wantConf: 0.6},
		{name: "internal _3_ is not a season marker", dirNameRaw: "Title_3_The_End…", wantTitle: "Title 3 The End…", wantSeason: 1, wantConf: 0.6},
		// Box 1.2 ground-truth rows.
		{name: "dot-scape with release tags", dirNameRaw: "From.S02.WEBDL.720p.Rus.Eng", wantTitle: "From", wantSeason: 2, wantConf: 1.0},
		{name: "ordinal marker, dash group tag, bracket tags", dirNameRaw: "Mairimashita! Iruma-kun 4th Season - AniLiberty [WEB-DL 1080p]", wantTitle: "Mairimashita! Iruma-kun", wantSeason: 4, wantConf: 1.0},
		{name: "bracket tags strip, title kept", dirNameRaw: "Kimi ga Shinu made Koi wo Shitai [WEB-DL 1080p]", wantTitle: "Kimi ga Shinu made Koi wo Shitai", wantSeason: 1, wantConf: 0.6},
		{name: "paren year strips", dirNameRaw: "Bleach S04 (2008)", wantTitle: "Bleach", wantSeason: 4, wantConf: 1.0},
		{name: "bare year stays in the title", dirNameRaw: "Quiet Meadow 2022", wantTitle: "Quiet Meadow 2022", wantSeason: 1, wantConf: 0.6},
		{name: "multi-word dash segment preserved whole", dirNameRaw: "Demon Slayer - Kimetsu no Yaiba Entertainment District Arc", wantTitle: "Demon Slayer - Kimetsu no Yaiba Entertainment District Arc", wantSeason: 1, wantConf: 0.6},
		// Box 1.2 derived rows (design.md D-8), neutralized.
		{name: "leading group bracket + rip combinator", dirNameRaw: "[Bluewave] Azure Harbor [BDRip 1080p x265 FLAC]", wantTitle: "Azure Harbor", wantSeason: 1, wantConf: 0.6},
		{name: "multi-bracket with source tag and acronym", dirNameRaw: "Crimson Vale [WEB-DL 1080p] [KTX]", wantTitle: "Crimson Vale", wantSeason: 1, wantConf: 0.6},
		{name: "cyrillic title + bracket", dirNameRaw: "Необычная гавань [WEB-DL 1080p]", wantTitle: "Необычная гавань", wantSeason: 1, wantConf: 0.6},
		{name: "trailing space normalizes", dirNameRaw: "Azure Harbor - Heaven's Feel ", wantTitle: "Azure Harbor - Heaven's Feel", wantSeason: 1, wantConf: 0.6},
		{name: "double space normalizes", dirNameRaw: "Azure Harbor  Unlimited Blade Works", wantTitle: "Azure Harbor Unlimited Blade Works", wantSeason: 1, wantConf: 0.6},
		{name: "non-leading paren matching no mask is preserved", dirNameRaw: "Title_(Shiro)", wantTitle: "Title (Shiro)", wantSeason: 1, wantConf: 0.6},
		// Group-tag shape pins: the trailing CamelCase tag strips after ANY
		// separator (space, dot, underscore — spec "Name-driven inference"),
		// not only after a dash.
		{name: "underscore-separated group tag strips", dirNameRaw: "Quiet_Meadow_FulL", wantTitle: "Quiet Meadow", wantSeason: 1, wantConf: 0.6},
		{name: "space-separated group tag strips", dirNameRaw: "Ivory Tower FulL", wantTitle: "Ivory Tower", wantSeason: 1, wantConf: 0.6},
		{name: "dot-separated group tag strips", dirNameRaw: "Quiet.Meadow.FulL", wantTitle: "Quiet Meadow", wantSeason: 1, wantConf: 0.6},
		// Canonical rows (unified-parser): the whole-token 720i joins the
		// resolution table once and strips from the title everywhere.
		{name: "whole-token 720i strips from the title", dirNameRaw: "Title 720i.mkv", backing: "file", wantTitle: "Title", wantSeason: 1, wantConf: 0.6},
		// Canonical row (unified-parser qa 4.1): the tagged film degenerate
		// case — the adapter still applies to the series document (its own
		// contract: a series document always parses), stripping the full
		// decoration and defaulting the package's Season 0 to 1.
		{name: "tagged film degenerate case", dirNameRaw: "Blue Horizon (2019) [WEB-DL 1080p x264] - FanGroup.mkv", backing: "file", wantTitle: "Blue Horizon", wantSeason: 1, wantConf: 0.6},
		// Canonical rows (film-name-parsing 1.3): the two real movie names as
		// file-backed series shapes — the dash-form group token strips after
		// the consumed 1080p, and the amzn source + dot-form codec leave no
		// title residue while the year stays in the title.
		{name: "dash-form group token strips", dirNameRaw: "Demon.Slayer.Kimetsu.No.Yaiba.Infinity.Castle.1080p.CR-Cassu.mkv", backing: "file", wantTitle: "Demon Slayer Kimetsu No Yaiba Infinity Castle", wantSeason: 1, wantConf: 0.6},
		{name: "amzn source and dot-form codec strip, year stays", dirNameRaw: "Chainsaw.Man.The.Movie.Reze.Arc.2025.1080p.AMZN.WEB-DL.H.264-EniaHD.mkv", backing: "file", wantTitle: "Chainsaw Man The Movie Reze Arc 2025", wantSeason: 1, wantConf: 0.6},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			backing := "directory"
			if tc.backing != "" {
				backing = tc.backing
			}
			parsed := seriesParsed(tc.dirNameRaw, tc.dirNameRaw)
			parsed["backing"] = backing
			applies, ns, _ := runChain(t, parsed)
			if !applies {
				t.Fatalf("Match did not apply to the series document")
			}
			if ns["title"] != tc.wantTitle {
				t.Fatalf("title = %q, want %q", ns["title"], tc.wantTitle)
			}
			if ns["season"] != tc.wantSeason {
				t.Fatalf("season = %v, want %v", ns["season"], tc.wantSeason)
			}
			if ns["dir_name_raw"] != tc.dirNameRaw {
				t.Fatalf("raw facts lost: %v", ns)
			}
		})
	}
}

// TestSeriesGrammarConfidence pins the explicit-vs-defaulted confidence shape:
// an explicit marker parses at 1.0, a defaulted season at 0.6.
func TestSeriesGrammarConfidence(t *testing.T) {
	impl := &parserImpl{}
	ctx := context.Background()
	match := func(raw string) float64 {
		t.Helper()
		st, err := structpb.NewStruct(seriesParsed(raw, raw))
		if err != nil {
			t.Fatalf("parsed struct: %v", err)
		}
		res, err := impl.Match(ctx, &metadatav1.MatchRequest{Item: &scannerv1.IdentifyResult{Parsed: st}})
		if err != nil || !res.GetApplies() {
			t.Fatalf("Match: err=%v applies=%v", err, res.GetApplies())
		}
		return res.GetConfidence()
	}
	if got := match("Black Clover S2"); got != 1.0 {
		t.Fatalf("explicit marker confidence = %v, want 1.0", got)
	}
	if got := match("Seishun Buta Yarou"); got != 0.6 {
		t.Fatalf("defaulted season confidence = %v, want 0.6", got)
	}
}

// TestEpisodeParse is box 3.3's chain half: the EPISODE document's
// sources.serial-parser carries the parsed season/episode plus the structured
// release fields the stem carries (unified-parser D-2) — and no series-level
// metadata (title, dir_name_raw) leaks into the episode namespace.
func TestEpisodeParse(t *testing.T) {
	applies, ns, _ := runChain(t, episodeParsed("Show/Show.S01E02.1080p.mkv"))
	if !applies {
		t.Fatalf("Match did not apply to the episode document")
	}
	if len(ns) != 3 {
		t.Fatalf("namespace = %v, want exactly season+episode+resolution", ns)
	}
	if ns["season"] != float64(1) || ns["episode"] != float64(2) {
		t.Fatalf("namespace = %v, want season 1 episode 2", ns)
	}
	if ns["resolution"] != "1080p" {
		t.Fatalf("namespace = %v, want resolution 1080p beside the identity keys", ns)
	}
}

// TestEpisodeNameGrammar is the episode-grammar table (change serial box 1.3):
// bare-number episode names yield a number and the season falls back through
// the stem marker, the series directory, and the default 1. Episode-only
// since film-name-parsing 2.1: the numberless and below-1 zero rows moved to
// TestFilmMatch (they apply as films now). Derived rows come from the
// real-collection shape inventory (design.md D-8), neutralized.
func TestEpisodeNameGrammar(t *testing.T) {
	cases := []struct {
		name        string
		rel         string
		wantSeason  float64
		wantEpisode float64
	}{
		// Ground-truth rows (spec delta "Bare-number episode filenames").
		{name: "bracket number with filename ordinal marker", rel: "Mairimashita_Iruma-kun_4th_Season/Mairimashita_Iruma-kun_4th_Season_[01].mkv", wantSeason: 4, wantEpisode: 1},
		{name: "dash number after rip bracket", rel: "Kimi ga Shinu made Koi wo Shitai/Kimi ga Shinu made Koi wo Shitai - 01 [1080p AVC AAC].mkv", wantSeason: 1, wantEpisode: 1},
		{name: "cyrillic marker with TV series marker", rel: "Aria TV 1/[01] Aria TV 1 01 серия.mkv", wantSeason: 1, wantEpisode: 1},
		{name: "group bracket and trailing dash number", rel: "Kimetsu no Yaiba - Yuukaku Hen/[Erai-raws] Kimetsu no Yaiba - Yuukaku Hen - 01.mkv", wantSeason: 1, wantEpisode: 1},
		// Derived rows (design.md D-8), neutralized.
		{name: "leading bracket number with cyrillic marker", rel: "Azure Harbor/[01] Azure Harbor 01 серия.mkv", wantSeason: 1, wantEpisode: 1},
		{name: "roman sequel in the episode stem", rel: "Azure Harbor II/[Bluewave] Azure Harbor II 01 [BDrip 1920x1080 x264 FLAC].mkv", wantSeason: 2, wantEpisode: 1},
		{name: "word-form marker in the episode stem", rel: "Crimson Vale Season 2/Crimson Vale Season 2 - 01 [1080p].mkv", wantSeason: 2, wantEpisode: 1},
		{name: "no marker anywhere defaults season 1", rel: "Ivory Tower/[Bluewave] Ivory Tower - 01 [BDRip 1080p x265 FLAC].mkv", wantSeason: 1, wantEpisode: 1},
		{name: "season falls back to the series directory marker", rel: "Azure Harbor TV-2/[Bluewave] Azure Harbor - 05 [BDRip 1080p].mkv", wantSeason: 2, wantEpisode: 5},
		{name: "unbracketed resolution token is not an episode number", rel: "Show/Show - 01 360p.mkv", wantSeason: 1, wantEpisode: 1},
		// Canonical row (unified-parser): the trailing-decoration bracket is
		// an episode candidate wherever it occurs (rightmost wins).
		{name: "trailing-decoration bracket after roman sequel", rel: "Show_Name_II/Show_Name_II_[01]_[HEVC].mkv", wantSeason: 2, wantEpisode: 1},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			applies, ns, reason := runChain(t, episodeParsed(tc.rel))
			if !applies {
				t.Fatalf("episode name %q did not apply (reason %q)", tc.rel, reason)
			}
			if ns["season"] != tc.wantSeason || ns["episode"] != tc.wantEpisode {
				t.Fatalf("namespace = %v, want season %v episode %v", ns, tc.wantSeason, tc.wantEpisode)
			}
		})
	}
}

// TestNamespaceEmission pins the structured release-field emission (unified-parser
// D-2): Match/Convert carry resolution, source, codec, language, and year beside
// the existing keys in sources["serial-parser"], for series and episode
// documents alike; a field with no matching token is omitted, never zeroed; and
// the existing skip and confidence behavior is unchanged.
func TestNamespaceEmission(t *testing.T) {
	t.Run("series namespace gains the release fields", func(t *testing.T) {
		applies, ns, _ := runChain(t, seriesParsed("From.S02.WEBDL.720p.Rus.Eng", "From.S02.WEBDL.720p.Rus.Eng"))
		if !applies {
			t.Fatalf("Match did not apply to the series document")
		}
		if ns["title"] != "From" || ns["season"] != float64(2) {
			t.Fatalf("existing keys changed: %v", ns)
		}
		if ns["resolution"] != "720p" || ns["source"] != "web-dl" {
			t.Fatalf("resolution/source = %v/%v, want 720p/web-dl", ns["resolution"], ns["source"])
		}
		if want := []any{"rus", "eng"}; !reflect.DeepEqual(ns["language"], want) {
			t.Fatalf("language = %v, want %v", ns["language"], want)
		}
		for _, absent := range []string{"codec", "year"} {
			if _, ok := ns[absent]; ok {
				t.Fatalf("series namespace carries %q with no matching token: %v", absent, ns)
			}
		}
	})

	t.Run("episode namespace gains codec and source", func(t *testing.T) {
		applies, ns, _ := runChain(t, episodeParsed("Show II/Show II - 01 [WEBRip 1080p HEVC].mkv"))
		if !applies {
			t.Fatalf("Match did not apply to the episode document")
		}
		if ns["season"] != float64(2) || ns["episode"] != float64(1) {
			t.Fatalf("existing keys changed: %v", ns)
		}
		if ns["resolution"] != "1080p" || ns["source"] != "webrip" {
			t.Fatalf("resolution/source = %v/%v, want 1080p/webrip", ns["resolution"], ns["source"])
		}
		if want := []any{"hevc"}; !reflect.DeepEqual(ns["codec"], want) {
			t.Fatalf("codec = %v, want %v", ns["codec"], want)
		}
		for _, absent := range []string{"language", "year"} {
			if _, ok := ns[absent]; ok {
				t.Fatalf("episode namespace carries %q with no matching token: %v", absent, ns)
			}
		}
	})

	t.Run("year joins when the name carries one", func(t *testing.T) {
		applies, ns, _ := runChain(t, seriesParsed("Bleach S04 (2008)", "Bleach S04 (2008)"))
		if !applies {
			t.Fatalf("Match did not apply to the series document")
		}
		if ns["year"] != float64(2008) {
			t.Fatalf("year = %v, want 2008", ns["year"])
		}
	})

	t.Run("no release tags emit no new keys", func(t *testing.T) {
		_, ns, _ := runChain(t, seriesParsed("Seishun Buta Yarou", "Seishun Buta Yarou"))
		if len(ns) != 3 { // title, dir_name_raw, season
			t.Fatalf("series namespace = %v, want exactly the three existing keys", ns)
		}
		_, ns, _ = runChain(t, episodeParsed("Show/[01] Episode.mkv"))
		if len(ns) != 2 { // season, episode
			t.Fatalf("episode namespace = %v, want exactly season+episode", ns)
		}
	})
}
